const items = $input.all();
const output = [];

for (const item of items) {
  const src = item.json || {};


  const cards =
    src.cards ||
    src.data?.cards ||
    [];


  const selectedMaakunta =
    src.filters?.maakunta ||
    src.maakunta ||
    "";

  for (const card of cards) {
    const location = card.location || {};
    const data = card.data || {};

    output.push({
      json: {
        "Lähde": "oikotie",
        "Maakunta": selectedMaakunta,

        "ID": String(card.cardId || ""),
        "URL": card.url || "",

        "Kaupunki":
          location.city ||
          location.municipality ||
          "",

        "Osoite":
