        "IN email": "",
        "RM löyty": "",
        "remontti": "",

        "raw_location": location,
        "raw_data": data
      }
    });
  }
}

return output;

const patterns = [
  /\biloq\b/i,
  /lukkoremont/i,
  /lukitusremont/i,
  /lukituksen uusim/i,
  /lukitusjärjestelmä[aä]n uusim/i,
  /lukosto(n)? uusim/i,
  /avaim(ien|et)? uusim/i,
  /sarjoit(us|ukset|taa|taminen)/i,
  /lukituks(en|en modernisointi)/i,
  /sähköinen lukitus/i,
  /älyluk/i,

  /kulunvalvonta/i,
  /kulunvalvontajärjestelm[aä]/i,
  /kulunvalvonnan uusim/i,
  /kulunvalvonnan päivitys/i,
  /kulunvalvonnan modernisointi/i,
  /kulunvalvonnan asennus/i,
  /kulunvalvontajärjestelm[aä]n uusim/i,
  /kulunvalvontajärjestelm[aä]n päivitys/i,
  /kulunvalvontajärjestelm[aä]n modernisointi/i,
  /kulunvalvontajärjestelm[aä]n asennus/i,
  /sähkölukitus/i,
  /ovipuhelinjärjestelm[aä]/i,
  /oviautomatiikka/i
];

function collectEvidence(text) {
  if (!text || typeof text !== "string") return [];

  const hits = [];

  for (const re of patterns) {
    const m = text.match(re);
    if (m) hits.push(m[0]);
  }

  return [...new Set(hits)];
}

return items.map(item => {
  const row = item.json;

  const tulevat = row["Tulev. Remontit"] || row["Tulev. remontit"] || row["tulevat_remontit"] || "";
  const taloyhtio = row["Taloyhtiö"] || row["taloyhtio"] || "";
  const yhteenveto = row["Yhteenveto"] || row["yhteenveto"] || "";
  const aiTeksti = row["AI_teksti"] || row["ai_teksti"] || "";
  const remontti = row["remontti"] || "";

  const primaryText = `${tulevat}`;
  const fallbackText = `${taloyhtio}\n${yhteenveto}\n${aiTeksti}\n${remontti}`;

  const primaryEvidence = collectEvidence(primaryText);
  const fallbackEvidence = collectEvidence(fallbackText);

  const evidence = primaryEvidence.length > 0 ? primaryEvidence : fallbackEvidence;
  const relevant = evidence.length > 0;

  return {
    json: {
      ...row,
      relevant,
      match_source:
        primaryEvidence.length > 0
          ? "Tulev. Remontit"
          : (fallbackEvidence.length > 0 ? "Muut kentät" : ""),
      evidence,
      remontti: evidence.join(", ")
    }
  };
});

const http = $json;
const listing = $('TRANSFORM – Build Iteration Payload').item.json || {};

const html = (http.pageHtml || "").slice(0, 200000);

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
  .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
  .replace(/<img[^>]*>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/gi, " ")
  .replace(/&amp;/gi, "&")
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/\s+/g, " ")
  .trim();

const startMarkers = [
  "Taloyhtiö",
  "Tulevat remontit",
  "Asunnon lisätiedot",
  "Perustiedot",
  "Kohdenumero",
  "Rakennuksen tiedot",
  "Asunnon kuvaus"
];

let cropped = text;
for (const marker of startMarkers) {
  const idx = text.indexOf(marker);
  if (idx >= 0) {
    cropped = text.slice(idx);
    break;
  }
}

const finalText = cropped.slice(0, 12000);

return {
  json: {
    ...listing,
    pageText: finalText,
    pageTextLength: finalText.length
  }
};

return items.map(item => {
  const tulevat = item.json["Tulev. Remontit"] || "";
  const yhteenveto = item.json["Yhteenveto"] || "";

  item.json.lead_analysis_text = `
Tulevat remontit:
${tulevat}

Yhteenveto:
${yhteenveto}
  `.trim();

  return item;
});

