  "maxcdn.bootstrapcdn.com",
  "service.giosg.com",
  "track.adform.net",
  "google.com",
  "google.fi",
  "w3.org",
  "upseller.cloud",
  "enento.com/sijoittajat",
  ".js",
  ".css",
  ".svg",
  ".png",
  ".jpg",
  ".jpeg",
  ".webp",
  "cookie",
  "consent"
];

const websites = unique(
  websiteMatches.filter(url => {
    const u = String(url || "").toLowerCase();
    if (!u) return false;
    if (badWebsitePatterns.some(x => u.includes(x))) return false;
    return true;
  })
);

// PUHELIMET yleisesti
const allPhoneMatches =
  combinedSearchText.match(/(?:\+358|0)\d(?:[\d ]{5,20}\d)/g) || [];

const allPhones = unique(
  allPhoneMatches
    .map(p => cleanPhone(p))
    .filter(p => {
      const digits = p.replace(/\D/g, "");
      return digits.length >= 8 && digits.length <= 15;
    })
);

let finderPrimaryPhone = "";
const finderLabelMatch =
  finderRaw.match(/Puhelin(?:numero)?[\s\S]{0,250}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i) ||
  finderRaw.match(/Soita[\s\S]{0,120}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i);

if (finderLabelMatch) {
  finderPrimaryPhone = cleanPhone(finderLabelMatch[1]);
}

let asiakastietoPrimaryPhone = "";
const asiakastietoLabelMatch =
  asiakastietoRaw.match(/Puhelin(?:numero)?[\s\S]{0,250}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i);

if (asiakastietoLabelMatch) {
  asiakastietoPrimaryPhone = cleanPhone(asiakastietoLabelMatch[1]);
}

const fallbackCandidatePhones = unique([
  asiakastietoPrimaryPhone,
  finderPrimaryPhone,
  ...allPhones
].filter(Boolean));

const fallbackPrimaryPhone =
  asiakastietoPrimaryPhone ||
  finderPrimaryPhone ||
  fallbackCandidatePhones[0] ||
  "";

const fallbackPrimaryWebsite = websites[0] || "";

let fallbackSourceHint = "";
if (asiakastietoRaw.trim() && (asiakastietoPrimaryPhone || emails.length || websites.length)) {
  fallbackSourceHint = "asiakastieto";
} else if (finderRaw.trim() && (finderPrimaryPhone || emails.length || websites.length)) {
  fallbackSourceHint = "finder";
} else if (finderRaw.trim()) {
  fallbackSourceHint = "finder";
}

const foundSomething =
  emails.length > 0 ||
  fallbackCandidatePhones.length > 0 ||
  websites.length > 0;

return {
  json: {
    ...base,
    fallbackStage: "company_search_responses_parsed",
    finderRaw,
    asiakastietoRaw,
    finderRawPreview: finderRaw.slice(0, 1500),
    asiakastietoRawPreview: asiakastietoRaw.slice(0, 1500),
    combinedSearchText: combinedSearchText.slice(0, 6000),

    finderPrimaryPhone,
    asiakastietoPrimaryPhone,

    debug_raw_keys: {
      baseKeys: Object.keys(base || {}),
      currentKeys: Object.keys(current || {})
    },

    fallbackCandidateEmails: emails,
    fallbackCandidatePhones,
    fallbackCandidateWebsites: websites,
    fallbackPrimaryPhone,
    fallbackPrimaryWebsite,
    fallbackSourceHint,
    fallbackFoundSomething: foundSomething
  }
};

const j = $json || {};

const rawPhones = Array.isArray(j.fallbackCandidatePhones) ? j.fallbackCandidatePhones : [];
const rawWebsites = Array.isArray(j.fallbackCandidateWebsites) ? j.fallbackCandidateWebsites : [];

const blacklistDomains = [
  "schema.org",
  "ogp.me",
  "twitter.com",
  "facebook.com",
  "instagram.com",
  "linkedin.com",
  "youtube.com",
  "youtu.be",
  "adx.adform.net",
  "google.com",
  "googletagmanager.com",
  "doubleclick.net",
  "gstatic.com",
  "tiktok.com"
];

function normalizePhone(phone) {
  if (!phone) return "";
  return String(phone)
    .replace(/[^\d+]/g, "")
    .trim();
}

function isValidPhone(phone) {
  const p = normalizePhone(phone);
  if (!p) return false;
  const digits = p.replace(/\D/g, "");
  return digits.length >= 6;
}

function normalizeWebsite(url) {
  if (!url) return "";
  return String(url).trim();
}

function isGoodWebsite(url) {
  if (!url) return false;

  const lower = url.toLowerCase();

  if (!lower.startsWith("http")) return false;

  return !blacklistDomains.some(domain => lower.includes(domain));
}

const cleanedPhones = [...new Set(
  rawPhones
    .map(normalizePhone)
    .filter(isValidPhone)
)];

const cleanedWebsites = [...new Set(
  rawWebsites
    .map(normalizeWebsite)
    .filter(isGoodWebsite)
)];

const primaryPhone =
  normalizePhone(j.fallbackPrimaryPhone) ||
  cleanedPhones[0] ||
  "";

const primaryWebsite =
  isGoodWebsite(j.fallbackPrimaryWebsite)
    ? j.fallbackPrimaryWebsite
    : (cleanedWebsites[0] || "");

return {
  json: {
    ...j,
    fallbackCandidatePhones: cleanedPhones,
    fallbackCandidateWebsites: cleanedWebsites,
    fallbackPrimaryPhone: primaryPhone,
    fallbackPrimaryWebsite: primaryWebsite,
    fallbackFoundSomething: cleanedPhones.length > 0 || cleanedWebsites.length > 0
  }
};

