const input = $json || {};


const raw =
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  input.response ||
  input.content ||
  input.message ||
  input.output ||
  "";


let cleaned = String(raw).trim()
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed = {};

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    fallback_isannoitsija: "",
    fallback_isannointiyhtio: "",
    fallback_in_puh: "",
    fallback_in_email: "",
    fallback_source: "",
    fallback_confidence: 0,
    parse_error: true,
    raw_response: cleaned,
  };
}


const normalizePhone = (value) => {
  if (!value) return "";
  return String(value)
    .replace(/[^\d+]/g, "")
    .trim();
};

const normalizeEmail = (value) => {
  if (!value) return "";
  return String(value).trim().toLowerCase();
};

const fallbackPhone = normalizePhone(parsed.fallback_in_puh);
const fallbackEmail = normalizeEmail(parsed.fallback_in_email);

return {
  json: {
    ...input,
    raw_ai_response: cleaned,

    fallback_isannoitsija: parsed.fallback_isannoitsija || "",
    fallback_isannointiyhtio: parsed.fallback_isannointiyhtio || "",
    fallback_in_puh: fallbackPhone,
    fallback_in_email: fallbackEmail,
    fallback_source: parsed.fallback_source || "",
    fallback_confidence: Number(parsed.fallback_confidence || 0),

    fallback_has_phone: !!fallbackPhone,
    fallback_has_email: !!fallbackEmail,
    fallback_has_any: !!fallbackPhone || !!fallbackEmail,
  }
};

const j = $json || {};

const originalPhone = (j["IN puh"] || "").toString().trim();
const originalEmail = (j["IN email"] || "").toString().trim();

const aiPhone = (j.fallback_in_puh || "").toString().trim();
const aiEmail = (j.fallback_in_email || "").toString().trim();

const parsedPhone = (j.fallbackPrimaryPhone || "").toString().trim();

const finalPhone = originalPhone || aiPhone || parsedPhone || "";
const finalEmail = originalEmail || aiEmail || "";

const usedFallbackPhone = !originalPhone && !!(aiPhone || parsedPhone);
const usedFallbackEmail = !originalEmail && !!aiEmail;

return {
  json: {
    ...j,

    fallbackEnrichmentApplied: usedFallbackPhone || usedFallbackEmail,

    "Isännöitsijä": j["Isännöitsijä"] || j.fallback_isannoitsija || "",
    "Isännöintiyhtiö": j["Isännöintiyhtiö"] || j.fallback_isannointiyhtio || "",

    "IN puh": finalPhone,
    "IN email": finalEmail,

    in_puh: finalPhone,
    in_email: finalEmail,

    fallback_source_used:
      usedFallbackPhone || usedFallbackEmail
        ? (j.fallback_source || j.fallbackSourceHint || "")
        : "",

    fallback_confidence_used:
      usedFallbackPhone || usedFallbackEmail
        ? Number(j.fallback_confidence || 0)
        : 0,

    final_contact_status:
      finalPhone && finalEmail
        ? "phone_and_email"
        : finalPhone
        ? "phone_only"
        : finalEmail
        ? "email_only"
        : "no_contact",

    shouldSendToCRM: true
  }
};

return {
  json: {
    ...$json,
    finderRaw: "",
    asiakastietoRaw: "",
    combinedSearchText: "",
    fallbackCandidateEmails: [],
    fallbackCandidatePhones: [],
    fallbackFoundSomething: false,
    fallbackStage: "company_search_responses_parsed"
  }
};

const item = $json;

const id = item.ID?.toString().trim() || '';
const url = item.URL?.toString().trim() || '';
const processedAt = item.processed_at?.toString().trim() || '';
const source = item['Lähde']?.toString().trim() || 'unknown';
const city = item['Kaupunki']?.toString().trim() || '';
const address = item['Osoite']?.toString().trim() || '';
const price = item['Hinta']?.toString().trim() || '';
const area = item['Alue']?.toString().trim() || '';
const summary = item['Yhteenveto']?.toString().trim() || '';
const housingCompany = item['Taloyhtiö']?.toString().trim() || '';
const futureRenovations = item['Tulev. Remontit']?.toString().trim() || '';
const rmFound = item['RM löyty']?.toString().trim() || '';
const managerCompany = item['Isännöitsijä']?.toString().trim() || '';
const managerPhone = item['IN puh']?.toString().trim() || '';
const managerEmail = item['IN email']?.toString().trim() || '';
const renovation = item['remontti']?.toString().trim() || item['Remontti']?.toString().trim() || '';
const managerSource = item['IN Lähde']?.toString().trim() || '';


const managerBusinessIdRaw =
  item['IN business_id'] ??
  item['IN y_tunnus'] ??
  item['IN Y-tunnus'] ??
  item['business_id'] ??
  item['y_tunnus'] ??
  item['Y-tunnus'] ??
  '';

const managerBusinessId = managerBusinessIdRaw?.toString().trim() || '';
const businessIdRegex = /^\d{7}-\d$/;

const externalId = `${source}-${id}`;
const title = `Liidi: ${address}, ${city} | ${source}`;

const notes = [
  `Lähde: ${source}`,
  `External ID: ${externalId}`,
  `URL: ${url}`,
  `Käsitelty: ${processedAt}`,
  `Kaupunki: ${city}`,
  `Osoite: ${address}`,
  `Taloyhtiö: ${housingCompany}`,
  `Hinta: ${price}`,
  `Alue: ${area}`,
  `RM löyty: ${rmFound}`,
  `Isännöitsijä: ${managerCompany}`,
  `Isännöitsijän puhelin: ${managerPhone}`,
  `Isännöitsijän email: ${managerEmail}`,
  `Isännöitsijän business_id: ${managerBusinessId}`,
  `IN lähde: ${managerSource}`,
  `Tulevat remontit: ${futureRenovations}`,
  `Remontti: ${renovation}`,
  `Yhteenveto: ${summary}`,
].join('\n');

const payload = {
  title,
  notes,
  value: 0,
  source_system: `n8n_${source}_leadgen`,
  external_id: externalId,
};


if (managerCompany && businessIdRegex.test(managerBusinessId)) {
  payload.company = {
    name: managerCompany,
    business_id: managerBusinessId,
  };

  if (managerPhone) payload.company.phone = managerPhone;
  if (managerEmail) payload.company.email = managerEmail;
}

return [
  {
    json: {
      ...item,
      pinsale_payload: payload,
    }
  }
];
